'use strict';
const KEY = 'dia-a-dia.v1';
const AREAS = ['Pessoal', 'Trabalho', 'Estudos'];
const VIEWS = {hoje:'Hoje', tarefas:'Tarefas', agenda:'Agenda', projetos:'Projetos', notas:'Notas'};
const COLLECTIONS = {task:'tasks',event:'events',project:'projects',note:'notes'};
const TITLES = {task:'tarefa',event:'compromisso',project:'projeto',note:'nota'};
const $ = (s, root=document) => root.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon = name => `<i data-lucide="${name}" aria-hidden="true"></i>`;
function today(){return new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
function dateObj(value){return new Date(`${value}T12:00:00`);}
function offsetDate(value,delta){const d=dateObj(value);d.setDate(d.getDate()+delta);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function dateLabel(date,opts={day:'numeric',month:'short'}){return date ? dateObj(date).toLocaleDateString('pt-BR',opts).replace(/\./g,'') : 'Sem prazo';}
function relativeDate(date){return !date?'Sem prazo':date===today()?'Hoje':date===offsetDate(today(),1)?'Amanhã':date===offsetDate(today(),-1)?'Ontem':dateLabel(date);}
const uid = () => crypto.randomUUID();
function sampleData(){const d=today();return {version:1,demo:true,tasks:[
  {id:'t1',title:'Definir as prioridades da semana',date:d,priority:'high',area:'Pessoal',project:'p1',done:false},
  {id:'t2',title:'Separar referências para o portfólio',date:d,priority:'high',area:'Trabalho',project:'p2',done:false},
  {id:'t3',title:'Reservar um tempo para estudar',date:d,priority:'normal',area:'Estudos',project:'p3',done:false},
  {id:'t4',title:'Organizar os arquivos do projeto',date:d,priority:'low',area:'Trabalho',project:'p2',done:true},
  {id:'t5',title:'Planejar as próximas leituras',date:offsetDate(d,1),priority:'normal',area:'Estudos',project:'p3',done:false},
  {id:'t6',title:'Revisar a rotina de organização',date:offsetDate(d,2),priority:'low',area:'Pessoal',project:'p1',done:false}
],events:[
  {id:'e1',title:'Planejamento do dia',date:d,time:'09:00',end:'09:30',area:'Pessoal',location:'Meu espaço'},
  {id:'e2',title:'Bloco de trabalho no portfólio',date:d,time:'14:00',end:'15:00',area:'Trabalho',location:'Tempo de foco'},
  {id:'e3',title:'Estudo e prática',date:d,time:'18:30',end:'19:15',area:'Estudos',location:'Em casa'},
  {id:'e4',title:'Revisão da semana',date:offsetDate(d,1),time:'17:00',end:'17:30',area:'Pessoal',location:''}
],projects:[
  {id:'p1',title:'Minha rotina',description:'Ajustar os horários e abrir espaço para o que importa.',area:'Pessoal',date:offsetDate(d,7),status:'active'},
  {id:'p2',title:'Portfólio pessoal',description:'Reunir projetos e preparar uma apresentação do meu trabalho.',area:'Trabalho',date:offsetDate(d,14),status:'active'},
  {id:'p3',title:'Plano de estudos',description:'Escolher um assunto e manter a prática durante a semana.',area:'Estudos',date:offsetDate(d,21),status:'active'}
],notes:[
  {id:'n1',title:'Uma coisa de cada vez',body:'Escolher até três prioridades.\nDeixar espaço entre os compromissos.\nRevisar o que ficou para amanhã.',updated:new Date().toISOString()},
  {id:'n2',title:'Ideias para experimentar',body:'Usar este espaço para anotar ideias, links e coisas que não quero esquecer.',updated:new Date().toISOString()}
]};}
let storageError=false;
function isValidDate(d){if(typeof d!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(d))return false;const value=dateObj(d);return !isNaN(value)&&offsetDate(d,0)===d;}
function validateData(data){
  if(!data||data.version!==1||typeof data.demo!=='boolean')return false;
  const str=(v,max=10000)=>typeof v==='string'&&v.length<=max;
  const date=v=>str(v,10)&&(v===''||isValidDate(v));
  const ids=new Set();
  for(const c of Object.values(COLLECTIONS)){
    if(!Array.isArray(data[c])||data[c].length>10000)return false;
    for(const item of data[c]){
      if(!item||!str(item.id,100)||!item.id||ids.has(item.id)||!str(item.title,180)||!item.title.trim())return false;
      ids.add(item.id);
      if(c!=='notes'&&(!AREAS.includes(item.area)||!date(item.date)))return false;
      if(c==='tasks'&&(!['high','normal','low'].includes(item.priority)||typeof item.done!=='boolean'||!str(item.project,100)))return false;
      if(c==='events'&&(!item.date||!/^([01]\d|2[0-3]):[0-5]\d$/.test(item.time)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(item.end)||item.end<=item.time||!str(item.location,300)))return false;
      if(c==='projects'&&(!str(item.description,1000)||!['active','paused','completed'].includes(item.status)))return false;
      if(c==='notes'&&(!str(item.body,10000)||!str(item.updated,40)||isNaN(Date.parse(item.updated))))return false;
    }
  }
  return data.tasks.every(t=>!t.project||data.projects.some(p=>p.id===t.project));
}
let data;
try{const saved=localStorage.getItem(KEY);if(saved){data=JSON.parse(saved);if(!validateData(data))throw new Error('Invalid saved data');}else{data=sampleData();localStorage.setItem(KEY,JSON.stringify(data));}}catch{storageError=true;data={version:1,demo:false,tasks:[],events:[],projects:[],notes:[]};}
let view='hoje',query='',taskFilter='pending',areaFilter='all',selectedDate=today(),editing=null,toastTimer;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(data));storageError=false;return true;}catch{storageError=true;toast('Não foi possível salvar. Exporte um backup antes de sair.',true);return false;}}
function announceSaved(message){if(persist())toast(message);render();}
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.classList.toggle('error',error);el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),5000);}
function icons(){if(window.lucide)lucide.createIcons({attrs:{'aria-hidden':'true'}});}
function sortedTasks(list){const rank={high:0,normal:1,low:2};return [...list].sort((a,b)=>Number(a.done)-Number(b.done)||(a.date||'9999').localeCompare(b.date||'9999')||rank[a.priority]-rank[b.priority]);}
function taskRow(t){const project=data.projects.find(p=>p.id===t.project);return `<div class="task-row ${t.done?'completed':''}"><label class="task-check"><input type="checkbox" data-toggle="${esc(t.id)}" aria-label="${esc((t.done?'Reabrir: ':'Concluir: ')+t.title)}" ${t.done?'checked':''}>${icon('check')}</label><div class="task-info"><button class="item-title" data-edit="task" data-id="${esc(t.id)}">${esc(t.title)}</button><div class="item-meta"><span class="area-dot ${esc(t.area)}"></span><span>${esc(t.area)}</span>${project?`<span class="meta-divider">/</span><span>${esc(project.title)}</span>`:''}<span class="meta-divider">·</span><span class="${t.date&&t.date<today()&&!t.done?'overdue':''}">${relativeDate(t.date)}${t.date&&t.date<today()&&!t.done?' · atrasada':''}</span></div></div><span class="badge ${t.done?'completed':t.priority}">${t.done?'Concluída':{high:'Prioridade alta',normal:'Normal',low:'Sem pressa'}[t.priority]}</span><button class="icon-button row-delete" data-delete="task" data-id="${esc(t.id)}" aria-label="${esc('Excluir tarefa: '+t.title)}">${icon('trash-2')}</button></div>`;}
function eventRow(e){return `<div class="event-row"><time class="event-time">${esc(e.time)}</time><div class="event-body ${esc(e.area)}"><button class="item-title" data-edit="event" data-id="${esc(e.id)}">${esc(e.title)}</button><div class="item-meta">${esc(e.time)} – ${esc(e.end)}${e.location?` <span class="meta-divider">·</span> ${esc(e.location)}`:''}</div></div><button class="icon-button row-delete" data-delete="event" data-id="${esc(e.id)}" aria-label="${esc('Excluir compromisso: '+e.title)}">${icon('trash-2')}</button></div>`;}
function projectCard(p){const tasks=data.tasks.filter(t=>t.project===p.id),done=tasks.filter(t=>t.done).length,percent=tasks.length?Math.round(done/tasks.length*100):0;return `<article class="project-card"><div class="project-card-top"><span class="project-icon ${esc(p.area)}">${icon({Pessoal:'sprout',Trabalho:'briefcase-business',Estudos:'book-open'}[p.area])}</span><span class="badge ${p.status==='completed'?'completed':'normal'}">${{active:'Em andamento',paused:'Em pausa',completed:'Concluído'}[p.status]}</span></div><button class="item-title" data-edit="project" data-id="${esc(p.id)}">${esc(p.title)}</button><p>${esc(p.description||'Adicione uma descrição para este projeto.')}</p><div class="project-progress"><span>${done} de ${tasks.length} tarefas</span><span>${percent}%</span></div><div class="progress-track" role="progressbar" aria-label="${esc('Tarefas concluídas em '+p.title)}" aria-valuenow="${percent}" aria-valuemin="0" aria-valuemax="100"><div class="progress-fill" style="width:${percent}%"></div></div><div class="project-footer"><span>${icon('calendar')} ${p.date?dateLabel(p.date):'Sem prazo'}</span><button class="icon-button" data-delete="project" data-id="${esc(p.id)}" aria-label="${esc('Excluir projeto: '+p.title)}">${icon('trash-2')}</button></div></article>`;}
function noteCard(n,compact=false){return `<article class="note-card"><div class="note-heading"><h2>${icon('notebook-pen')} ${compact?'Nota rápida':'Anotação'}</h2><button class="icon-button" data-edit="note" data-id="${esc(n.id)}" aria-label="${esc('Editar nota: '+n.title)}">${icon('pencil')}</button></div><button class="item-title" data-edit="note" data-id="${esc(n.id)}">${esc(n.title)}</button><p class="note-content">${esc(compact&&n.body.length>200?n.body.slice(0,200)+'…':n.body)}</p><div class="note-footer"><span>Editada em ${new Date(n.updated).toLocaleDateString('pt-BR')}</span><button class="icon-button" data-delete="note" data-id="${esc(n.id)}" aria-label="${esc('Excluir nota: '+n.title)}">${icon('trash-2')}</button></div></article>`;}
function empty(title,description,type){return `<div class="empty-state">${icon('sprout')}<h3>${title}</h3><p>${description}</p>${type?`<button class="button secondary" data-new="${type}">${icon('plus')} Adicionar ${TITLES[type]}</button>`:''}</div>`;}
function link(label,to){return `<a href="#${to}" class="text-link">${label} ${icon('arrow-up-right')}</a>`;}
function heading(title,subtitle,type){return `<section class="page-heading"><div><p class="eyebrow">${view==='hoje'?'UM POUCO MAIS DE CLAREZA':'MEU ESPAÇO / '+VIEWS[view].toUpperCase()}</p><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${view==='hoje'?`<span class="date-pill">${icon('calendar-days')}${dateLabel(today(),{day:'numeric',month:'long'})}</span>`:''}${type?`<button class="button primary" data-new="${type}">${icon('plus')}${type==='task'?'Nova tarefa':type==='event'?'Novo compromisso':type==='project'?'Novo projeto':'Nova nota'}</button>`:''}</div></section>`;}
function weekCalendar(){const day=dateObj(selectedDate).getDay(),start=offsetDate(selectedDate,-(day===0?6:day-1));return `<div class="panel-head"><h2>${icon('calendar-days')} Sua agenda</h2><div class="calendar-heading"><button class="icon-button" data-week="-7" aria-label="Semana anterior">${icon('chevron-left')}</button><span>${dateLabel(selectedDate,{month:'short',year:'numeric'})}</span><button class="icon-button" data-week="7" aria-label="Próxima semana">${icon('chevron-right')}</button></div></div><div class="week">${Array.from({length:7},(_,i)=>{const d=offsetDate(start,i);return `<button class="day-button ${d===selectedDate?'selected':''} ${d===today()?'today':''}" data-date="${d}" aria-label="${dateLabel(d,{weekday:'long',day:'numeric',month:'long'})}" aria-pressed="${d===selectedDate}"><span class="weekday">${['SEG','TER','QUA','QUI','SEX','SÁB','DOM'][i]}</span><span>${dateObj(d).getDate()}</span><span class="event-dot ${data.events.some(e=>e.date===d)?'':'empty'}"></span></button>`;}).join('')}</div>`;}
function eventsForDate(){return data.events.filter(e=>e.date===selectedDate).sort((a,b)=>a.time.localeCompare(b.time));}
function dashboard(){const day=today(),due=data.tasks.filter(t=>t.date===day),done=due.filter(t=>t.done).length,percent=due.length?Math.round(done/due.length*100):0,urgent=data.tasks.filter(t=>!t.done&&t.priority==='high'&&(!t.date||t.date<=day)),meetings=data.events.filter(e=>e.date===day),tomorrow=data.tasks.filter(t=>!t.done&&t.date===offsetDate(day,1)),active=data.projects.filter(p=>p.status==='active'),focus=sortedTasks(data.tasks.filter(t=>(!t.done&&(!t.date||t.date<=day))||(t.done&&t.date===day))).slice(0,5),events=eventsForDate();
const summary=due.length||meetings.length?`Você tem ${meetings.length} compromisso${meetings.length===1?'':'s'} hoje e ${due.length-done} tarefa${due.length-done===1?'':'s'} para concluir.${urgent.length?' Comece pelas prioridades.':' Escolha por onde começar.'}`:'Seu dia ainda está em branco. Adicione uma tarefa ou reserve um horário na agenda.';
return heading('Um dia de cada vez.','Sua agenda, suas prioridades e espaço para as ideias.','task')+
`<section class="summary-banner"><div class="summary-copy"><span class="sun-medallion">${icon('sun')}</span><div><h2>${due.length&&done===due.length?'Tarefas do dia concluídas.':'Vamos organizar o seu dia?'}</h2><p>${summary}</p></div></div><div class="daily-progress"><div class="progress-ring" style="--progress:${percent}%" role="progressbar" aria-label="Progresso das tarefas de hoje" aria-valuenow="${percent}" aria-valuemin="0" aria-valuemax="100"><span>${percent}%</span></div><div><strong>Seu progresso</strong><small>${done} de ${due.length} tarefas do dia</small></div></div></section>
<section class="stats-grid" aria-label="Resumo do dia">${[{label:'Compromissos hoje',number:meetings.length,detail:'na sua agenda',icon:'calendar-days',color:'orange'},{label:'Tarefas prioritárias',number:urgent.length,detail:'para dar atenção',icon:'flag',color:'orange'},{label:'Projetos ativos',number:active.length,detail:'em andamento',icon:'layers',color:'purple'},{label:'Para amanhã',number:tomorrow.length,detail:'tarefas com prazo',icon:'arrow-up-right',color:''}].map(s=>`<div class="stat"><span class="stat-label">${s.label}</span><span class="stat-icon ${s.color}">${icon(s.icon)}</span><strong class="stat-number">${String(s.number).padStart(2,'0')}</strong><span class="stat-detail">${s.detail}</span></div>`).join('')}</section>
<div class="dashboard-grid"><div class="column"><section class="panel"><div class="panel-head"><h2>${icon('circle-check')} Em foco hoje</h2>${link('Ver tarefas','tarefas')}</div>${focus.length?focus.map(taskRow).join(''):empty('Tudo em dia por aqui.','Adicione uma tarefa para escolher seu próximo passo.','task')}<div class="panel-bottom"><button class="text-link" data-new="task">${icon('plus')} Adicionar tarefa</button></div></section>${data.notes.length?noteCard([...data.notes].sort((a,b)=>b.updated.localeCompare(a.updated))[0],true):`<section class="panel">${empty('Guarde uma ideia.','Um lugar para o que você não quer esquecer.','note')}</section>`}</div><div class="column"><section class="panel calendar-panel">${weekCalendar()}<p class="agenda-label">${relativeDate(selectedDate)} · ${events.length} compromisso${events.length===1?'':'s'}</p>${events.length?events.map(eventRow).join(''):empty('Um espaço na agenda.','Reserve tempo para o que precisa fazer.','event')}<div class="panel-bottom"><button class="text-link" data-new="event">${icon('plus')} Adicionar compromisso</button></div></section></div></div>
<section class="dashboard-projects"><div class="section-heading"><h2>Seus projetos</h2>${link('Ver todos','projetos')}</div>${data.projects.length?`<div class="project-grid">${data.projects.slice(0,3).map(projectCard).join('')}</div>`:`<div class="panel">${empty('Uma ideia pode virar projeto.','Agrupe tarefas em torno de um objetivo.','project')}</div>`}</section>`;
}
function tasksView(){const tasks=sortedTasks(data.tasks.filter(t=>(taskFilter==='all'||(taskFilter==='done'?t.done:!t.done))&&(areaFilter==='all'||t.area===areaFilter)));return heading('Um próximo passo.','Tire as pendências da cabeça e coloque por aqui.','task')+`<div class="filters"><div class="tabs" role="group" aria-label="Status das tarefas">${[['pending','Pendentes'],['done','Concluídas'],['all','Todas']].map(([v,l])=>`<button data-filter="${v}" class="${v===taskFilter?'active':''}" aria-pressed="${v===taskFilter}">${l}</button>`).join('')}</div><select class="filter-select" id="area-filter" aria-label="Filtrar tarefas por área"><option value="all">Todas as áreas</option>${AREAS.map(a=>`<option ${a===areaFilter?'selected':''}>${a}</option>`).join('')}</select><span class="toolbar-note">${tasks.length} tarefa${tasks.length===1?'':'s'}</span></div><section class="panel">${tasks.length?tasks.map(taskRow).join(''):empty('Nenhuma tarefa neste filtro.','Você pode trocar o filtro ou adicionar uma tarefa.','task')}</section>`;}
function agendaView(){const events=eventsForDate();return heading('Tempo bem reservado.','Organize os compromissos e os seus momentos de foco.','event')+`<div class="large-agenda"><section class="panel calendar-panel">${weekCalendar()}<div class="panel-bottom"><button class="text-link" data-date="${today()}">${icon('corner-down-left')} Voltar para hoje</button><label class="field" style="margin-top:10px"><span>Ir para uma data</span><input type="date" id="agenda-date" value="${selectedDate}" min="1900-01-01" max="9999-12-31"></label></div></section><section class="panel"><div class="panel-head"><h2>${dateLabel(selectedDate,{weekday:'long',day:'numeric',month:'long'})}</h2><span class="toolbar-note">${events.length} compromisso${events.length===1?'':'s'}</span></div>${events.length?events.map(eventRow).join(''):empty('Seu tempo está livre por aqui.','Adicione um compromisso para este dia.','event')}</section></div>`;}
function projectsView(){return heading('Ideias em movimento.','Agrupe as tarefas e acompanhe o que está avançando.','project')+(data.projects.length?`<div class="project-grid">${data.projects.map(projectCard).join('')}</div>`:`<section class="panel">${empty('Qual projeto vem primeiro?','Comece com um nome e um próximo passo.','project')}</section>`);}
function notesView(){return heading('Pode anotar.','Ideias, lembretes e pensamentos que merecem um lugar.','note')+(data.notes.length?`<div class="notes-grid">${[...data.notes].sort((a,b)=>b.updated.localeCompare(a.updated)).map(n=>noteCard(n)).join('')}</div>`:`<section class="panel">${empty('Uma página em branco.','Guarde aqui uma ideia, uma lista ou uma referência.','note')}</section>`);}
function searchView(){const normalize=v=>String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),q=normalize(query),matches=v=>normalize(v).includes(q);const groups=[['Tarefas',data.tasks.filter(t=>matches(t.title+' '+t.area)),taskRow],['Agenda',data.events.filter(e=>matches(e.title+' '+e.location)),eventRow],['Projetos',data.projects.filter(p=>matches(p.title+' '+p.description)),projectCard],['Notas',data.notes.filter(n=>matches(n.title+' '+n.body)),noteCard]];return `<section class="page-heading"><div><p class="eyebrow">BUSCA NO SEU ESPAÇO</p><h1>Resultados da busca</h1><p>Buscando por “${esc(query)}”</p></div></section><div class="search-results">${groups.some(g=>g[1].length)?groups.filter(g=>g[1].length).map(([label,items,renderItem])=>`<section class="search-section"><h2>${label} <span class="muted">(${items.length})</span></h2><div class="panel">${items.map(i=>renderItem(i)).join('')}</div></section>`).join(''):empty('Nenhum resultado por aqui.','Tente outra palavra ou um trecho do título.')}</div>`;}
function render(){view=Object.hasOwn(VIEWS,location.hash.slice(1))?location.hash.slice(1):'hoje';$('#view-label').textContent=query?'Busca':VIEWS[view];document.title=`${query?'Busca':VIEWS[view]} · OrgaLume`;$('nav').querySelectorAll('a').forEach(a=>{const active=a.dataset.view===view&&!query;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#task-count').textContent=data.tasks.filter(t=>!t.done).length;const notice=data.demo?`<div class="demo-notice"><span>${icon('info')} Você está explorando dados de exemplo.</span><button data-action="reset">Começar do zero ${icon('arrow-right')}</button></div>`:'';$('#main').innerHTML=(storageError?'<div class="storage-warning" role="alert">Não foi possível carregar ou salvar os dados deste navegador. Exporte um backup antes de sair. Você pode tentar restaurar um backup em Dados e preferências.</div>':'')+notice+(query?searchView():({hoje:dashboard,tarefas:tasksView,agenda:agendaView,projetos:projectsView,notas:notesView}[view])());icons();}
function field(label,name,value='',type='text',extra=''){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function selectField(label,name,options,value){return `<label class="field"><span>${label}</span><select name="${name}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`;}).join('')}</select></label>`;}
function openEditor(type,id){const existing=id?data[COLLECTIONS[type]].find(v=>v.id===id):null;if(id&&!existing)return;editing={type,id};const item=existing||{date:type==='event'?selectedDate:today(),area:'Pessoal',priority:'normal',status:'active',time:'09:00',end:'10:00'};$('#modal-title').textContent=(id?'Editar ':'Nov'+(['task','note'].includes(type)?'a ':'o '))+TITLES[type];let fields=field('Título','title',item.title||'','text','required maxlength="180" placeholder="O que você tem em mente?"');const dateInput=field(type==='event'?'Data':'Prazo (opcional)','date',item.date,'date',`${type==='event'?'required ':''}min="1900-01-01" max="9999-12-31"`),areaInput=selectField('Área','area',AREAS,item.area);
if(type==='task')fields+=`<div class="field-row">${dateInput}${selectField('Prioridade','priority',[['high','Alta'],['normal','Normal'],['low','Sem pressa']],item.priority)}</div><div class="field-row">${areaInput}${selectField('Projeto (opcional)','project',[['','Sem projeto'],...data.projects.map(p=>[p.id,p.title])],item.project||'')}</div>`;
if(type==='event')fields+=`<div class="field-row">${dateInput}${areaInput}</div><div class="field-row">${field('Início','time',item.time,'time','required')}${field('Fim','end',item.end,'time','required')}</div>${field('Local ou contexto (opcional)','location',item.location||'','text','maxlength="300" placeholder="Ex.: em casa, chamada, tempo de foco"')}`;
if(type==='project')fields+=`<label class="field"><span>Descrição (opcional)</span><textarea name="description" maxlength="1000" placeholder="O que você quer realizar?">${esc(item.description||'')}</textarea></label><div class="field-row">${dateInput}${areaInput}</div>${selectField('Andamento','status',[['active','Em andamento'],['paused','Em pausa'],['completed','Concluído']],item.status)}`;
if(type==='note')fields+=`<label class="field"><span>Anotação</span><textarea name="body" rows="7" maxlength="10000" placeholder="Comece a escrever…">${esc(item.body||'')}</textarea></label>`;
$('#form-fields').innerHTML=fields;icons();$('#editor').showModal();setTimeout(()=>$('[name="title"]',$('#editor')).focus(),0);}
$('#entry-form').addEventListener('submit',e=>{e.preventDefault();const form=e.target,values=Object.fromEntries(new FormData(form)),{type,id}=editing;values.title=values.title.trim();if(!values.title){form.elements.title.setCustomValidity('Escreva um título.');form.elements.title.reportValidity();return;}if(type==='event'&&values.end<=values.time){form.elements.end.setCustomValidity('O horário final deve ser depois do início.');form.elements.end.reportValidity();return;}if(type==='note')values.updated=new Date().toISOString();const collection=data[COLLECTIONS[type]],index=collection.findIndex(v=>v.id===id);if(index>=0)collection[index]={...collection[index],...values};else collection.push({id:uid(),...(type==='task'?{done:false}:{}),...values});$('#editor').close();announceSaved(id?'Alterações salvas.':'Adicionado ao seu espaço.');});
$('#entry-form').addEventListener('input',e=>{if(e.target.setCustomValidity)e.target.setCustomValidity('');const end=$('[name="end"]',e.currentTarget);if(end)end.setCustomValidity('');});
function confirmAction(title,message,button='Confirmar'){return new Promise(resolve=>{const dialog=$('#confirmation');$('#confirm-title').textContent=title;$('#confirm-message').textContent=message;$('#confirm-button').textContent=button;dialog.returnValue='';dialog.addEventListener('close',()=>resolve(dialog.returnValue==='confirm'),{once:true});dialog.showModal();});}
async function removeItem(type,id){const col=COLLECTIONS[type],item=data[col].find(v=>v.id===id);if(!item)return;const extra=type==='project'?' As tarefas vinculadas serão mantidas, sem projeto.':'';if(await confirmAction(`Excluir ${TITLES[type]}?`,`“${item.title}” será removido.${extra}`,'Excluir')){data[col]=data[col].filter(v=>v.id!==id);if(type==='project')data.tasks.forEach(t=>{if(t.project===id)t.project='';});announceSaved('Item excluído.');}}
async function resetData(){if(await confirmAction('Começar do zero?',data.demo?'Isso apaga os exemplos e qualquer item que você tenha adicionado. Exporte um backup antes se quiser guardar.':'Isso apaga todos os itens deste navegador. Exporte um backup antes se quiser guardar.','Limpar e começar')){data={version:1,demo:false,tasks:[],events:[],projects:[],notes:[]};$('#settings').close();query='';$('#search').value='';announceSaved('Espaço pronto para receber seus dados.');}}
function exportData(){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`orgalume-backup-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exportado. Guarde em um lugar seguro.');}
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>5000000){toast('O backup precisa ter menos de 5 MB.',true);return;}try{const imported=JSON.parse(await file.text());if(!validateData(imported))throw new Error('invalid');if(await confirmAction('Restaurar este backup?','Os itens atuais serão substituídos pelos dados do arquivo.','Restaurar')){data=imported;$('#settings').close();announceSaved('Backup restaurado.');}}catch{toast('Arquivo inválido. Use um backup exportado pelo OrgaLume.',true);}});
document.addEventListener('click',e=>{const button=e.target.closest('button,a');if(!button)return;if(button.dataset.new)openEditor(button.dataset.new);if(button.dataset.edit)openEditor(button.dataset.edit,button.dataset.id);if(button.dataset.delete)removeItem(button.dataset.delete,button.dataset.id);if(button.dataset.filter){taskFilter=button.dataset.filter;render();}if(button.dataset.date){selectedDate=button.dataset.date;render();}if(button.dataset.week){selectedDate=offsetDate(selectedDate,Number(button.dataset.week));render();}const action=button.dataset.action;if(action==='close-modal')$('#editor').close();if(action==='settings')$('#settings').showModal();if(action==='close-settings')$('#settings').close();if(action==='reset')resetData();if(action==='export')exportData();if(action==='import')$('#import-file').click();if(button.matches('a[href^="#"]')&&button.getAttribute('href')!=='#main'){query='';$('#search').value='';if(location.hash===button.hash)render();}});
document.addEventListener('change',e=>{if(e.target.dataset.toggle){const t=data.tasks.find(v=>v.id===e.target.dataset.toggle);if(t){t.done=e.target.checked;const id=t.id;announceSaved(t.done?'Tarefa concluída. Um passo a menos.':'Tarefa reaberta.');const next=[...document.querySelectorAll('[data-toggle]')].find(el=>el.dataset.toggle===id);next?.focus();}}if(e.target.id==='area-filter'){areaFilter=e.target.value;render();}if(e.target.id==='agenda-date'&&isValidDate(e.target.value)){selectedDate=e.target.value;render();}});
$('#search').addEventListener('input',e=>{query=e.target.value.trim();render();});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#search').focus();}if(e.key==='Escape'&&document.activeElement===$('#search')){$('#search').value='';query='';render();$('#search').blur();}});
window.addEventListener('hashchange',()=>{query='';$('#search').value='';render();window.scrollTo({top:0});});
window.addEventListener('storage',e=>{if(e.key===KEY){try{const next=JSON.parse(e.newValue);if(validateData(next)){data=next;render();toast('Dados atualizados em outra aba.');}}catch{toast('Não foi possível ler a atualização de outra aba.',true);}}});
let currentDay=today();setInterval(()=>{const next=today();if(next!==currentDay){if(selectedDate===currentDay)selectedDate=next;currentDay=next;render();}},60000);
render();
